-- 20260623_activity_overviews_seed_prob.sql
-- 활동 개요 시드 — 확률과통계 66개 미니활동.
-- activity_overviews(slug PK) 에 슬러그별 개요를 upsert. 재실행 멱등(overview 갱신).
-- 이후 관리자가 /admin/overviews 에서 직접 수정 가능.
--
-- 적용:  Supabase SQL 에디터에서 실행.
-- 검증:  select count(*) from activity_overviews where slug like 'probability%';

on conflict (slug) do update set
  overview = excluded.overview,
  updated_at = now();
