insert into public.activity_overviews (slug, overview, updated_at) values
  ($s$probability_new/mini/rep_perm_password$s$, $ov$자릿수와 사용할 숫자의 개수를 바꿔 가며 만들 수 있는 비밀번호의 경우의 수가 어떻게 변하는지 직접 조작·관찰하고, 중복을 허용하는 경우(중복순열)와 허용하지 않는 경우의 차이를 비교하는 활동.$ov$, now()),
  ($s$probability_new/mini/rep_perm_morse$s$, $ov$점·선 두 기호로 길이가 다른 신호를 만들며 각 자리에 기호를 중복해 쓸 때의 신호 개수를 중복순열로 세고, 기호 종류를 늘리면 경우의 수가 어떻게 달라지는지 탐구하는 활동.$ov$, now()),
